"less":{a:[{tr:"s./z. daha az",ex:"Households that install solar panels typically spend less money on electricity each year.",exTr:"Güneş paneli kuran haneler, genellikle her yıl elektriğe daha az para harcar.",exs:[{"ex":"The revised process used less material, but the team also checked whether the resulting product remained suitable for repeated handling.","exTr":"Gözden geçirilmiş işlem daha az malzeme kullandı; ancak ekip ortaya çıkan ürünün tekrar tekrar elle kullanılmaya uygun kalıp kalmadığını da kontrol etti."}]}],kl:[{en:"less than",tr:"-den az"},{en:"more or less",tr:"aşağı yukarı"},{en:"no less than",tr:"tam ..., -den az değil"}]},
