"reach":{a:[{tr:"f. ulaşmak, erişmek, varmak",ex:"After years of research, the team finally reached a breakthrough in cancer treatment.",exTr:"Yıllar süren araştırmanın ardından ekip, sonunda kanser tedavisinde bir atılıma ulaştı.",yz:4,exs:[{"ex":"The library extended its delivery service to reach readers who could not travel easily, while checking whether the new arrangements met their actual needs.","exTr":"Kütüphane kolayca yolculuk yapamayan okurlara ulaşmak için teslimat hizmetini genişletirken yeni düzenlemelerin onların gerçek ihtiyaçlarını karşılayıp karşılamadığını kontrol etti."}]},{tr:"i. erişim, menzil",ex:"The new telescope has a reach far beyond that of any previous instrument built by the agency.",exTr:"Yeni teleskop, ajansın daha önce ürettiği herhangi bir araçtan çok daha geniş bir erişime sahip.",yz:2}],kl:[{en:"reach an agreement",tr:"anlaşmaya varmak"},{en:"reach a conclusion",tr:"bir sonuca varmak"},{en:"within reach",tr:"ulaşılabilir, erişilebilir"}]},
