"based":{a:[{tr:"f. dayandırdı, temellendirdi (base fiilinin geçmiş/V3 biçimi)",ex:"The researchers based their conclusions on long-term observations.",exTr:"Araştırmacılar sonuçlarını uzun süreli gözlemlere dayandırdı.",yz:4,exs:[{"ex":"The author based her account on correspondence between ordinary residents rather than relying exclusively on statements issued by local officials.","exTr":"Yazar, anlatısını yalnızca yerel görevlilerin yayımladığı açıklamalara dayanmak yerine sıradan sakinlerin yazışmalarına dayandırdı."}]},{tr:"s. dayanan, -e dayalı",ex:"The clinic's treatment plan is based on the latest evidence from peer-reviewed medical journals.",exTr:"Kliniğin tedavi planı, hakemli tıp dergilerindeki en güncel kanıtlara dayanmaktadır.",yz:3}],kl:[{en:"based on sth",tr:"bir şeye dayalı, dayanarak"},{en:"based on the assumption that",tr:"... varsayımına dayanarak"},{en:"evidence-based medicine",tr:"kanıta dayalı tıp"}]},
"enable":{a:[{tr:"f. sağlamak, olanak tanımak, mümkün kılmak",ex:"Wireless sensors enable farmers to monitor soil moisture without walking through every field.",exTr:"Kablosuz sensörler, çiftçilerin her tarlayı dolaşmadan toprak nemini izlemesini sağlar.",exs:[{"ex":"Audio descriptions enable visitors to follow the exhibition's visual arguments even when the original images are difficult or impossible for them to see.","exTr":"Sesli betimlemeler, özgün görüntüleri görmek kendileri için zor veya imkânsız olsa bile ziyaretçilerin serginin görsel olarak sunduğu görüşleri takip etmesini sağlar."}]}],kl:[{en:"enable sb to do sth",tr:"birinin bir şey yapmasını sağlamak"},{en:"enable the development of sth",tr:"bir şeyin gelişimini mümkün kılmak"}]},
"job":{a:[{tr:"i. iş, meslek",ex:"Automation is expected to eliminate certain jobs while creating entirely new categories of employment.",exTr:"Otomasyonun bazı işleri ortadan kaldırırken tümüyle yeni istihdam alanları yaratması bekleniyor.",yz:4,exs:[{"ex":"She accepted a temporary job at the printing company to learn how design decisions were translated into production schedules and material requirements.","exTr":"Tasarım kararlarının üretim programlarına ve malzeme ihtiyaçlarına nasıl dönüştürüldüğünü öğrenmek için matbaa şirketinde geçici bir işi kabul etti."}]},{tr:"i. görev, vazife",ex:"It is the school's job to ensure that every child feels safe and included.",exTr:"Her çocuğun kendini güvende ve dahil hissetmesini sağlamak okulun görevidir.",yz:2}],kl:[{en:"do a good job",tr:"işi iyi yapmak"},{en:"lose one's job",tr:"işini kaybetmek"},{en:"job satisfaction",tr:"iş tatmini"}]},
"mental":{a:[{tr:"s. zihinsel, ruhsal, akli",ex:"Untreated mental health conditions can significantly affect a person's academic and professional performance.",exTr:"Tedavi edilmeyen ruh sağlığı sorunları, bir kişinin akademik ve mesleki performansını önemli ölçüde etkileyebilir.",exs:[{"ex":"The designer asked users to describe their mental picture of the booking process before showing them the sequence built into the software.","exTr":"Tasarımcı, yazılıma yerleştirilmiş sırayı göstermeden önce kullanıcılardan rezervasyon sürecine ilişkin zihinsel tasarımlarını betimlemelerini istedi."}]}],kl:[{en:"mental health",tr:"ruh sağlığı"},{en:"mental illness",tr:"akıl hastalığı"},{en:"mental ability",tr:"zihinsel yetenek"}]},
"serious":{a:[{tr:"s. ciddi, önemli",ex:"Untreated infections can quickly develop into a serious threat to a patient's overall health.",exTr:"Tedavi edilmeyen enfeksiyonlar, hastanın genel sağlığı için hızla ciddi bir tehdide dönüşebilir.",exs:[{"ex":"The missing dates were a serious limitation because the argument depended on establishing which of two developments had occurred first.","exTr":"Sav iki gelişmeden hangisinin önce meydana geldiğini belirlemeye dayandığı için eksik tarihler ciddi bir sınırlılıktı."}]}],kl:[{en:"a serious threat to sth",tr:"bir şeye ciddi bir tehdit"},{en:"serious consequences",tr:"ciddi sonuçlar"},{en:"a serious illness",tr:"ciddi bir hastalık"}]},
"true":{a:[{tr:"s. doğru, gerçek",ex:"Researchers found the hypothesis to be true only under very specific environmental conditions.",exTr:"Araştırmacılar, hipotezin yalnızca çok özel çevresel koşullar altında doğru olduğunu tespit etti.",yz:4,exs:[{"ex":"An explanation may sound convincing without being true, so the students were asked to identify evidence that could distinguish competing accounts.","exTr":"Bir açıklama doğru olmadan da ikna edici gelebileceği için öğrencilerden rakip anlatımları birbirinden ayırabilecek kanıtları belirlemeleri istendi."}]},{tr:"z. tam olarak, doğru biçimde",ex:"A well-balanced wheel should run true without wobbling, even when the vehicle reaches high speeds.",exTr:"İyi dengelenmiş bir tekerlek, araç yüksek hızlara ulaştığında bile sallanmadan tam olarak dönmelidir.",yz:1}],kl:[{en:"be true of sth",tr:"bir şey için geçerli olmak"},{en:"hold true",tr:"geçerli olmak, doğru kalmak"},{en:"come true",tr:"gerçekleşmek"}]},
