"conditions":{a:[{tr:"i. koşullar, şartlar",ex:"Extreme weather conditions have made it increasingly difficult for farmers to predict harvest yields.",exTr:"Aşırı hava koşulları, çiftçilerin hasat verimini tahmin etmesini giderek zorlaştırdı.",yz:4,exs:[{"ex":"Working conditions varied considerably between departments, despite a single set of rules governing the organisation as a whole.","exTr":"Kuruluşun tamamını düzenleyen tek bir kurallar bütünü bulunmasına rağmen çalışma koşulları birimler arasında önemli ölçüde değişiyordu."}]},{tr:"i. rahatsızlık, hastalık durumu",ex:"The patient was diagnosed with a rare genetic condition that severely limits bone growth in childhood.",exTr:"Hastaya, çocuklukta kemik gelişimini ciddi şekilde sınırlayan nadir bir genetik rahatsızlık teşhisi kondu.",yz:3}],kl:[{en:"working conditions",tr:"çalışma koşulları"},{en:"living conditions",tr:"yaşam koşulları"},{en:"under certain conditions",tr:"belirli koşullar altında"}]},
